int main(void) { if(!g_getenv("GEANY_RUN_GUI_TESTS") || !g_getenv("DISPLAY")) return 77;restoring=g_getenv("GEANY_TEST_APPEARANCE_RESTORE")!=NULL;gchar *dir=g_dir_make_tmp("interface-appearance-XXXXXX",NULL),*settings=g_build_filename(dir,"insight",NULL),*file=g_build_filename(dir,"profile.c",NULL),*geany=g_build_filename(dir,"geany.conf",NULL);g_mkdir_with_parents(settings,0700);config=g_build_filename(settings,"interface-style.conf",NULL);g_file_set_contents(file,code,-1,NULL);g_file_set_contents(geany,"[geany]\nconfirm_exit=false\n",-1,NULL);if(restoring) g_file_set_contents(config,"[interface]\nversion=1\nstyle=macos\nreduce-transparency=true\n",-1,NULL);gchar *args[]={"appearance","--new-instance","--no-session","--config",dir,file,NULL};g_log_set_always_fatal(G_LOG_FATAL_MASK|G_LOG_LEVEL_CRITICAL);g_timeout_add(250,step,NULL);return main_lib(6,args); }
